cat > src/App.tsx <<'EOF'
import {PageConstructor, PageConstructorProvider, Theme} from '@gravity-ui/page-constructor';
import {useThemeType} from '@gravity-ui/uikit';

import {content} from './content';

export function App() {
    const themeType = useThemeType();

    return (
        <PageConstructorProvider theme={themeType === 'dark' ? Theme.Dark : Theme.Light}>
            <PageConstructor content={content} />
        </PageConstructorProvider>
    );
}
EOF
cat > src/index.css <<'EOF'
*,
*::before,
*::after {
    box-sizing: border-box;
}

body {
    margin: 0;
}
EOF
python3 - <<'EOF'
p='src/main.tsx'
s=open(p).read()
s=s.replace("import '@gravity-ui/uikit/styles/styles.css';\n","import '@gravity-ui/uikit/styles/styles.css';\nimport '@gravity-ui/page-constructor/styles/styles.scss';\nimport './index.css';\n")
open(p,'w').write(s)
p='index.html'
s=open(p).read().replace('lang="en"','lang="ru"').replace('Gravity UI eval','TimeTrack — учёт времени команды')
open(p,'w').write(s)
EOF
